package cn.sixnine.filmlog;
import android.app.Instrumentation;
import android.os.*;
import android.location.Location;
import android.graphics.*;
import java.util.*;

public final class LocatedRecordInstrumentation extends Instrumentation {
    static void check(boolean ok,String label){if(!ok)throw new AssertionError(label);}
    static Location fix(){Location point=new Location("synthetic-test");point.setLatitude(31.2304);point.setLongitude(121.4737);point.setAccuracy(8);point.setTime(System.currentTimeMillis());point.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos());return point;}
    interface Attempt{void run()throws Exception;}
    static void rejected(Attempt action,String label)throws Exception{try{action.run();}catch(IllegalArgumentException|java.io.IOException expected){return;}throw new AssertionError(label);}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){Bundle out=new Bundle();try{
        android.content.Context c=getTargetContext();check(c.getPackageName().equals("cn.sixnine.filmlog.media.tests"),"test identity");c.deleteDatabase("film-log.db");try(LogStore logs=new LogStore(c)){
            String roll=logs.addRoll("Located fixture","Synthetic 400","Camera",400,1),id=UUID.randomUUID().toString();long tap=System.currentTimeMillis()-100;
            rejected(()->logs.recordLocated(id,roll,tap,-10,480,"","","","","","",null),"null fix accepted");Location stale=fix();stale.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos()-61000000000L);rejected(()->logs.recordLocated(id,roll,tap,-10,480,"","","","","","",stale),"stale fix accepted");Location invalid=fix();invalid.setLatitude(Double.NaN);rejected(()->logs.recordLocated(id,roll,tap,-10,480,"","","","","","",invalid),"NaN accepted");check(logs.roll(roll).count==0&&logs.roll(roll).state.equals("active"),"failures never advance frames");
            for(boolean speedKnown:new boolean[]{false,true}){Location recent=fix();long age=speedKnown?45000:25000;recent.setTime(System.currentTimeMillis()-age);recent.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos()-age*1000000L);if(speedKnown){recent.setSpeed(.2f);recent.setSpeedAccuracyMetersPerSecond(.1f);}long originalTime=recent.getTime();String cacheRoll=logs.addRoll("Recent fix","Test","",400,36);String cacheShot=logs.recordLocated(UUID.randomUUID().toString(),cacheRoll,tap,0,480,"","","","","","",recent);check(logs.shot(cacheShot).locationTime==originalTime&&logs.shot(cacheShot).accuracy==recent.getAccuracy()&&logs.shot(cacheShot).tapped==tap,"recent fix preserves real time/accuracy and original tap");logs.deleteRoll(cacheRoll,1);}
            Location moving=fix();moving.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos()-20000000000L);moving.setSpeed(15);rejected(()->logs.recordLocated(UUID.randomUUID().toString(),roll,tap,0,480,"","","","","","",moving),"old moving fix accepted");Location uncertain=fix();uncertain.setElapsedRealtimeNanos(SystemClock.elapsedRealtimeNanos()-45000000000L);uncertain.setSpeed(.1f);uncertain.setSpeedAccuracyMetersPerSecond(5);rejected(()->logs.recordLocated(UUID.randomUUID().toString(),roll,tap,0,480,"","","","","","",uncertain),"uncertain speed extended old fix");
            Location first=fix();logs.recordLocated(id,roll,tap,-10,480,"","","","","","",first);LogStore.Shot shot=logs.shot(id);check(shot.status.equals("acquired")&&shot.lat==first.getLatitude()&&shot.lon==first.getLongitude()&&shot.captured==tap-10000&&shot.zone==480,"atomic timestamp/coordinates");check(logs.roll(roll).state.equals("active")&&logs.roll(roll).count==1,"nominal frame remains active");Location later=fix();later.setLatitude(32);logs.recordLocated(id,roll,tap,-10,480,"","","","","","",later);check(logs.roll(roll).count==1&&logs.shot(id).lat==first.getLatitude(),"replay never changes coordinates");String beyond=logs.recordLocated(UUID.randomUUID().toString(),roll,tap,-10,480,"","","","","","",fix());check(logs.shot(beyond).frame==2&&logs.shot(beyond).lat!=null&&logs.roll(roll).capacity==1,"located extra frame retains capacity");
            String legacyRoll=logs.addRoll("Legacy fixture","Old","Camera",400,36),legacy=UUID.randomUUID().toString();logs.insertWithId(legacy,legacyRoll,tap,-10,480,"denied","","","","","","");rejected(()->logs.recordLocated(legacy,legacyRoll,tap,-10,480,"","","","","","",fix()),"legacy location overwritten");check(logs.shot(legacy).lat==null&&logs.shot(legacy).status.equals("denied"),"old missing GPS stays historical");
            String referenceRoll=logs.addRoll("Located reference","Synthetic 400","Camera",400,36),token=UUID.randomUUID().toString();Bitmap image=Bitmap.createBitmap(160,160,Bitmap.Config.ARGB_8888);image.eraseColor(Color.GREEN);ReferencePhotos.capture(c,token,image);String recorded=ReferencePhotos.record(c,logs,token,referenceRoll,tap,-10,480,"acquired","8","1/125","","test","","",fix());check(logs.shot(recorded).lat!=null&&ReferencePhotos.forShot(logs,recorded).equals(token)&&!ReferencePhotos.draft(c,token).exists(),"reference and coordinates commit together");check(ReferencePhotos.record(c,logs,token,referenceRoll,tap,-10,480,"acquired","8","1/125","","test","","",fix()).equals(recorded)&&logs.roll(referenceRoll).count==1,"located reference replay");
            String failed=UUID.randomUUID().toString();ReferencePhotos.capture(c,failed,image);logs.getWritableDatabase().execSQL("CREATE TRIGGER located_ref_failure BEFORE INSERT ON reference_photos BEGIN SELECT RAISE(ABORT,'injected reference failure'); END");boolean failedAsExpected=false;try{ReferencePhotos.record(c,logs,failed,referenceRoll,tap,-10,480,"acquired","8","1/125","","test","","",fix());}catch(android.database.sqlite.SQLiteException expected){failedAsExpected=true;}logs.getWritableDatabase().execSQL("DROP TRIGGER located_ref_failure");check(failedAsExpected&&logs.roll(referenceRoll).count==1&&ReferencePhotos.draft(c,failed).exists()&&!new ScanStore(c,logs).file(failed).exists(),"SQL failure rolls back row and media, retains draft");image.recycle();
            java.io.ByteArrayOutputStream archive=new java.io.ByteArrayOutputStream();FilmBackup.write(c,logs,archive);int rollsBefore=logs.rolls().size();try(FilmBackup.Prepared prepared=FilmBackup.inspect(c,new java.io.ByteArrayInputStream(archive.toByteArray()))){FilmBackup.restore(c,logs,prepared);}check(logs.rolls().size()==rollsBefore*2,"located data backup appends safely");int restoredReferences=0;for(LogStore.Roll r:logs.rolls())for(LogStore.Shot s:logs.shots(r.id))if(!ReferencePhotos.forShot(logs,s.id).isEmpty()){check(s.lat!=null&&s.status.equals("acquired"),"reference coordinates survive remapping");restoredReferences++;}check(restoredReferences==2,"reference/shot ID namespaces restore separately");
            try(android.database.Cursor rows=logs.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM shots WHERE status='pending'",null)){rows.moveToFirst();check(rows.getInt(0)==0,"no transient pending new records committed");}
        }
        out.putString("stream","PASS: missing/stale/nonfinite fix rejection, no frame advance, atomic coordinates/time/zone beyond nominal capacity, idempotence without coordinate overwrite, legacy missing GPS protected; reference plus location transaction, replay, SQL failure row/media rollback and draft retention; located references/coordinates backup restore\n");finish(-1,out);
    }catch(Throwable e){out.putString("stream",android.util.Log.getStackTraceString(e));finish(0,out);}}
}
